def parse_line(line, sep=","):
    fields=[]; cur=""; quoted=False; i=0; n=len(line)
    while i < n:
        ch=line[i]
        if quoted:
            if ch=='"':
                if i+1<n and line[i+1]=='"':
                    cur+='"'; i+=2; continue
                quoted=False; i+=1; continue
            cur+=ch
        else:
            if ch=='"':
                quoted=True
            elif ch==sep:
                fields.append(cur); cur=""; i+=1; continue
            else:
                cur+=ch
        i+=1
    if quoted: raise ValueError("unterminated quote in CSV line")
    fields.append(cur)
    return fields

